#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

const int MOD1=998244353, MOD2=1e9+7, BASE=1e6;
vector<int> digits[7];
int prefix_sum[7];
long long total_numbers, order_counter, answer;

void generate_sequences(int start, int length) {
    ++order_counter;
    digits[length].push_back((order_counter - start + MOD1) % MOD1);
    (prefix_sum[length] += digits[length].back()) %= MOD2;
    if (length == 6) return;
    for (int digit=0; digit<=9; ++digit) {
        generate_sequences(start*10 + digit, length+1);
    }
}

void process_numbers(long long current) {
    if (current > total_numbers) return;
    if (current*BASE + BASE - 1 <= total_numbers && current*BASE*10 > total_numbers) {
        long long temp_order = order_counter;
        for (int i=0, multiplier=1; i<=6; ++i, multiplier*=10) {
            int size=digits[i].size();
            int delta=((temp_order - current*multiplier) % MOD1 + MOD1) % MOD1;
            int position=lower_bound(digits[i].begin(), digits[i].end(), MOD1 - delta) - digits[i].begin();
            answer = (answer + 1LL*delta*size + prefix_sum[i]) % MOD2;
            answer = (answer - 1LL*(size - position)*MOD1 + MOD2) % MOD2;
            order_counter += size;
        }
        return;
    }
    ++order_counter;
    answer = (answer + ((order_counter - current) % MOD1 + MOD1) % MOD1) % MOD2;
    for (int digit=0; digit<=9; ++digit) {
        process_numbers(current*10 + digit);
    }
}

int main() {
    long long n_input;
    cin >> n_input;
    total_numbers = n_input;
    generate_sequences(0,0);
    order_counter=0;
    for (int i=0; i<=6; ++i) sort(digits[i].begin(), digits[i].end());
    for (int i=1; i<=9; ++i) process_numbers(i);
    cout << answer;
    return 0;
}
